# Animatica Rig window (generated by animatica-assets pipeline/dcc/maya_picker.py).
# Runs as the scriptNode "animatica_picker" of <asset>_controls.ma when the scene
# opens. With script nodes disabled (Safe Mode / secure loading) run this file by
# hand in the Script Editor (Python tab):
#     exec(open(r"<folder>/<asset>_picker.py").read())
# then animatica_rig_show() opens the window again at any time.
import json
import math
import sys

import maya.api.OpenMaya as om
import maya.cmds as cmds

ANIMATICA_RIG_ATTR = "animaticaRig"
ANIMATICA_WINDOW = "AnimaticaRig"
ANIMATICA_STATE = {"root": None}


# --- rig lookup ------------------------------------------------------------------

def animatica_rig_roots():
    """Every root_ctrl (any namespace) holding an Animatica rig layout."""
    found = cmds.ls("root_ctrl", recursive=True, type="transform") or []
    return sorted(r for r in found
                  if cmds.attributeQuery(ANIMATICA_RIG_ATTR, node=r, exists=True))


def _animatica_root(root=None):
    if root:
        return root
    roots = animatica_rig_roots()
    if ANIMATICA_STATE["root"] in roots:
        return ANIMATICA_STATE["root"]
    if not roots:
        raise RuntimeError("no Animatica rig (root_ctrl.%s) in the scene" % ANIMATICA_RIG_ATTR)
    return roots[0]


def animatica_rig_layout(root=None):
    """The layout stored on root_ctrl, rig node names prefixed with the root's
    namespace (deform joint names kept as stored)."""
    root = _animatica_root(root)
    layout = json.loads(cmds.getAttr(root + "." + ANIMATICA_RIG_ATTR))
    ns = root.rpartition(":")[0]
    if not ns:
        return layout

    def q(n):
        return ns + ":" + n if n else n

    layout["root"], layout["group"] = q(layout["root"]), q(layout["group"])
    layout["controls"] = dict((q(k), v) for k, v in layout["controls"].items())
    for limb in layout["limbs"].values():
        for k in ("settings", "ik", "toeIk", "pole", "fkGroup", "ikGroup", "handle"):
            limb[k] = q(limb[k])
        for k in ("fk", "ikJoints", "fkJoints", "blend"):
            limb[k] = [q(n) for n in limb[k]]
    return layout


# --- matrices (row vectors: world = local * parent) --------------------------------

def _world(node):
    return om.MMatrix(cmds.getAttr(node + ".worldMatrix[0]"))


def _rotation(m):
    """m without translation and scale."""
    return om.MTransformationMatrix(m).rotation().asMatrix()


def _translation(m):
    return om.MVector(m[12], m[13], m[14])


def _settable(plug):
    return cmds.getAttr(plug, settable=True)


def _set_world(ctrl, target, translate=False):
    """Pose ctrl so its world rotation (and translation) equals target's.
    Locked channels are left alone."""
    local = om.MMatrix(cmds.getAttr(ctrl + ".matrix"))
    parent = local.inverse() * _world(ctrl)  # offsetParentMatrix * parent world
    tm = om.MTransformationMatrix(target * parent.inverse())
    euler = tm.rotation().reorder(cmds.getAttr(ctrl + ".rotateOrder"))
    angle_unit = om.MAngle.uiUnit()
    for axis, value in zip("XYZ", (euler.x, euler.y, euler.z)):
        plug = ctrl + ".rotate" + axis
        if _settable(plug):
            cmds.setAttr(plug, om.MAngle(value).asUnits(angle_unit))
    if translate:
        t = tm.translation(om.MSpace.kTransform)
        dist_unit = om.MDistance.uiUnit()
        for axis, value in zip("XYZ", (t.x, t.y, t.z)):
            plug = ctrl + ".translate" + axis
            if _settable(plug):
                cmds.setAttr(plug, om.MDistance(value).asUnits(dist_unit))


def _set_ikfk(limb, value):
    plug = limb["settings"] + ".ikfk"
    if _settable(plug):
        cmds.setAttr(plug, value)


# --- match and switch ----------------------------------------------------------------

def animatica_rig_to_fk(limb_key, root=None):
    """IK -> FK without a jump: FK controls onto the ik_ joints, then ikfk = 1."""
    limb = animatica_rig_layout(root)["limbs"][limb_key]
    cmds.undoInfo(openChunk=True, chunkName="animatica_rig_to_fk")
    try:
        targets = [_world(j) for j in limb["ikJoints"]]
        for ctrl, target in zip(limb["fk"], targets):  # parent first
            _set_world(ctrl, target)
        _set_ikfk(limb, 1.0)
    finally:
        cmds.undoInfo(closeChunk=True)


def animatica_rig_to_ik(limb_key, root=None):
    """FK -> IK without a jump: the IK control onto the fk_ end joint, the pole on
    the chain plane at chain length on the bend side, IK toe = FK toe, ikfk = 0."""
    limb = animatica_rig_layout(root)["limbs"][limb_key]
    cmds.undoInfo(openChunk=True, chunkName="animatica_rig_to_ik")
    try:
        fk = [_world(j) for j in limb["fkJoints"]]
        ik_ctrl, ik_end = limb["ik"], limb["ikJoints"][2]

        # the IK end joint follows the control through a constant orientation
        # offset (orientConstraint, maintainOffset): ik_end = offset * ctrl
        ctrl_w = _world(ik_ctrl)
        offset = _rotation(_world(ik_end)) * _rotation(ctrl_w).inverse()
        new = om.MTransformationMatrix(offset.inverse() * _rotation(fk[2]))
        # the handle sits under the control; put the handle on the fk_ end joint
        handle_in_ctrl = _world(limb["handle"]) * ctrl_w.inverse()
        p0 = _translation(handle_in_ctrl * new.asMatrix())
        new.setTranslation(_translation(fk[2]) - p0, om.MSpace.kTransform)
        _set_world(ik_ctrl, new.asMatrix(), translate=True)

        # pole: on the chain plane, chain length from the middle joint, on the
        # side the middle joint sticks out to (straight chain: keep the pole's side)
        a, b, c = (_translation(m) for m in fk[:3])
        line = (c - a).normal()
        out = (b - a) - line * ((b - a) * line)
        if out.length() < 1e-3 * limb["length"]:
            pole_now = _translation(_world(limb["pole"])) - b
            out = pole_now - line * (pole_now * line)
        if out.length() > 1e-9:
            target = om.MTransformationMatrix()
            target.setTranslation(b + out.normal() * limb["length"], om.MSpace.kTransform)
            _set_world(limb["pole"], target.asMatrix(), translate=True)

        # toe: toe_ik.rotate drives the ik_ toe joint like toe_fk drives the fk_ one
        if limb.get("toeIk") and len(limb["fk"]) > 3:
            src, dst = limb["fk"][3], limb["toeIk"]
            e = om.MEulerRotation([math.radians(v) for v in cmds.getAttr(src + ".rotate")[0]],
                                  cmds.getAttr(src + ".rotateOrder"))
            e = e.reorder(cmds.getAttr(dst + ".rotateOrder"))
            for axis, value in zip("XYZ", (e.x, e.y, e.z)):
                plug = dst + ".rotate" + axis
                if _settable(plug):
                    cmds.setAttr(plug, math.degrees(value))
        _set_ikfk(limb, 0.0)
    finally:
        cmds.undoInfo(closeChunk=True)


def animatica_rig_set_all(value, root=None):
    """ikfk of every limb (0 = IK, 1 = FK), no matching - like Blender's All IK/FK."""
    for limb in animatica_rig_layout(root)["limbs"].values():
        _set_ikfk(limb, float(value))


def animatica_rig_select(ctrl, add=None):
    """Select ctrl; add to the selection when Shift is held (or add=True)."""
    if add is None:
        add = bool(cmds.getModifiers() & 1)
    cmds.select(ctrl, add=add, replace=not add)


# --- window --------------------------------------------------------------------------

def _ctrl_color(ctrl):
    for shape in cmds.listRelatives(ctrl, shapes=True, fullPath=True) or []:
        if cmds.attributeQuery("overrideColorRGB", node=shape, exists=True):
            return list(cmds.getAttr(shape + ".overrideColorRGB")[0])
    return [0.4, 0.4, 0.4]


def _short(ctrl, side):
    name = ctrl.rpartition(":")[2]
    if side and name.endswith("_" + side):
        name = name[:-len(side) - 1]
    return name


def _button(ctrl, side, width=None):
    kw = {"width": width} if width else {}
    cmds.button(label=_short(ctrl, side), backgroundColor=_ctrl_color(ctrl),
                annotation="Select " + ctrl + " (Shift: add to the selection)",
                command=lambda *_: animatica_rig_select(ctrl), **kw)


def _pick_root(root):
    ANIMATICA_STATE["root"] = root
    animatica_rig_show()


def animatica_rig_ui():
    """Fill the workspaceControl (its uiScript)."""
    roots = animatica_rig_roots()
    cmds.scrollLayout(childResizable=True)
    cmds.columnLayout(adjustableColumn=True, rowSpacing=4)
    if not roots:
        cmds.text(label="No Animatica rig (root_ctrl) in the scene.")
        return
    root = _animatica_root()
    ANIMATICA_STATE["root"] = root
    if len(roots) > 1:
        menu = cmds.optionMenu(label="Rig", changeCommand=_pick_root)
        for r in roots:
            cmds.menuItem(label=r)
        cmds.optionMenu(menu, edit=True, value=root)
    layout = animatica_rig_layout(root)
    controls = layout["controls"]

    cmds.frameLayout(label="Rig", collapsable=True, marginWidth=4)
    for attr in ("controlRig", "stretch", "hideInactive"):
        if cmds.attributeQuery(attr, node=root, exists=True):
            cmds.attrControlGrp(attribute=root + "." + attr)
    cmds.setParent("..")

    cmds.frameLayout(label="IK / FK", collapsable=True, marginWidth=4)
    cmds.rowLayout(numberOfColumns=2)
    cmds.button(label="All IK", command=lambda *_: animatica_rig_set_all(0.0, root))
    cmds.button(label="All FK", command=lambda *_: animatica_rig_set_all(1.0, root))
    cmds.setParent("..")
    for key in sorted(layout["limbs"]):
        limb = layout["limbs"][key]
        name, _, side = key.partition("_")
        cmds.attrControlGrp(attribute=limb["settings"] + ".ikfk",
                            label="%s %s" % (name.capitalize(), side))
        cmds.rowLayout(numberOfColumns=2)
        cmds.button(label="-> FK", annotation="Match FK to IK, then switch to FK",
                    command=lambda *_, k=key: animatica_rig_to_fk(k, root))
        cmds.button(label="-> IK", annotation="Match IK to FK, then switch to IK",
                    command=lambda *_, k=key: animatica_rig_to_ik(k, root))
        cmds.setParent("..")
    cmds.setParent("..")

    # body map: L | centre | R (screen-left side first, as the Blender picker)
    cmds.frameLayout(label="Picker (Shift: add)", collapsable=True, marginWidth=4)
    cmds.rowLayout(numberOfColumns=3, adjustableColumn=2)
    centre = [c for c, v in controls.items() if v["side"] is None]
    for side in ("L", None, "R"):
        cmds.columnLayout(adjustableColumn=True)
        if side is None:
            for c in reversed(centre):  # head on top, root at the bottom
                _button(c, None)
        else:
            cmds.text(label=side)
            for c, v in controls.items():
                if v["side"] == side and v["kind"] != "finger":
                    _button(c, side)
        cmds.setParent("..")
    cmds.setParent("..")
    for side in ("L", "R"):
        fingers = {}
        for c, v in controls.items():
            if v["side"] == side and v["kind"] == "finger":
                fingers.setdefault(_short(c, side).split("_")[0], []).append(c)
        if not fingers:
            continue
        cmds.text(label="Fingers " + side, align="left")
        cmds.rowLayout(numberOfColumns=len(fingers))
        for finger, ctrls in fingers.items():
            cmds.columnLayout()
            cmds.text(label=finger.capitalize())
            for c in ctrls:
                _button(c, side, width=60)
            cmds.setParent("..")
        cmds.setParent("..")
    cmds.setParent("..")


def animatica_rig_show():
    """Open (or rebuild) the Animatica Rig window; None in batch mode."""
    if cmds.about(batch=True):
        return None
    if cmds.workspaceControl(ANIMATICA_WINDOW, exists=True):
        cmds.deleteUI(ANIMATICA_WINDOW)
    cmds.workspaceControl(ANIMATICA_WINDOW, label="Animatica Rig", retain=False,
                          floating=True, initialWidth=420, initialHeight=720,
                          uiScript="animatica_rig_ui()")
    return ANIMATICA_WINDOW


# the window's uiScript runs in __main__ whoever exec'ed this code. The scriptNode
# already runs in __main__; "import __main__" there makes Maya 2027 print a
# broken traceback (__main__.__spec__ is None), hence sys.modules.
_main = sys.modules["__main__"]
if vars(_main) is not globals():
    for _name in ("animatica_rig_roots", "animatica_rig_layout", "animatica_rig_to_fk",
                  "animatica_rig_to_ik", "animatica_rig_set_all", "animatica_rig_select",
                  "animatica_rig_show", "animatica_rig_ui"):
        setattr(_main, _name, globals()[_name])

if not cmds.about(batch=True):
    cmds.evalDeferred(animatica_rig_show)  # after the scene has finished loading
